// The JS API of @almucantar/core. The functions come from the WebAssembly module (almucantar.mjs,
// generated by Emscripten). This file adds the defaults of the options, so a caller can give
// only the fields that it wants to change. The defaults come from C++, so they cannot drift.

import createAlmucantarModule from "./almucantar.mjs";

/** The model that calculates the position of the sun. */
export const SolarModel = Object.freeze({ noaa: 0, astronomyEngine: 1 });

/** The body of terrainEvents(). */
export const Body = Object.freeze({ sun: 0, moon: 1 });

/** The result kind of sunEvents(). */
export const DayKind = Object.freeze({ normal: 0, polarDay: 1, polarNight: 2 });

/** The meaning of screen.orientation / Android Surface.ROTATION_*: the value is the ordinal. */
export const ScreenRotation = Object.freeze({ rotation0: 0, rotation90: 1, rotation180: 2, rotation270: 3 });

/** The variance of a heading that is not known at all, in square degrees. */
export const UNKNOWN_HEADING_VARIANCE_DEG2 = 180 * 180;

function deepFreeze(o) {
  for (const v of Object.values(o)) if (typeof v === "object" && v !== null) deepFreeze(v);
  return Object.freeze(o);
}

function merge(defaults, value) {
  const result = { ...defaults, ...(value ?? {}) };
  if (defaults.atmosphere) result.atmosphere = { ...defaults.atmosphere, ...(value?.atmosphere ?? {}) };
  if (defaults.camera) result.camera = { ...defaults.camera, ...(value?.camera ?? {}) };
  if (defaults.deviceToEnu) result.deviceToEnu = { ...defaults.deviceToEnu, ...(value?.deviceToEnu ?? {}) };
  return result;
}

/**
 * Loads the WebAssembly module and returns the API. Options go to the Emscripten module, for
 * example { locateFile } if almucantar.wasm is at another URL.
 */
export async function load(moduleOptions = {}) {
  const m = await createAlmucantarModule(moduleOptions);
  const d = deepFreeze(m.defaults());
  const view = (v) => merge(d.view, v);
  return Object.freeze({
    version: () => m.version(),
    sunriseAltitudeDeg: d.sunriseAltitudeDeg,
    defaults: d,
    sunPosition: (unixUtc, observer, options) => m.sunPosition(unixUtc, observer, merge(d.sunOptions, options)),
    sunEvents: (observer, startUtc, endUtc, options) =>
      m.sunEvents(observer, startUtc, endUtc, merge(d.eventOptions, options)),
    sunPath: (observer, startUtc, endUtc, options) =>
      m.sunPath(observer, startUtc, endUtc, merge(d.pathOptions, options)),
    moonPosition: (unixUtc, observer, options) => m.moonPosition(unixUtc, observer, merge(d.moonOptions, options)),
    moonIlluminatedFraction: (unixUtc) => m.moonIlluminatedFraction(unixUtc),
    readElevationGeotiff: (data, level = 0) => m.readElevationGeotiff(data, level),
    elevationGeotiffPrefixSize: (header, level) => m.elevationGeotiffPrefixSize(header, level),
    elevationTiles: (observer, maxDistanceM) => m.elevationTiles(observer, maxDistanceM),
    mapTiles: (observer, maxDistanceM, zoom) => m.mapTiles(observer, maxDistanceM, zoom),
    terrariumGrid: (rgba, width, height, tile) => m.terrariumGrid(rgba, width, height, tile),
    horizonProfile: (observer, tiles, options) => m.horizonProfile(observer, tiles, merge(d.horizonOptions, options)),
    terrainAltitudeDeg: (profile, azimuthDeg) => m.terrainAltitudeDeg(profile, azimuthDeg),
    terrainEvents: (observer, profile, startUtc, endUtc, options) =>
      m.terrainEvents(observer, profile, startUtc, endUtc, merge(d.terrainEventOptions, options)),
    magneticDeclinationDeg: (observer, unixUtc) => m.magneticDeclinationDeg(observer, unixUtc),
    cameraFromFov: (width, height, horizontalFovDeg) => m.cameraFromFov(width, height, horizontalFovDeg),
    project: (v, direction) => m.project(view(v), direction),
    unproject: (v, point) => m.unproject(view(v), point),
    projectLine: (v, line) => m.projectLine(view(v), line),
    projectPath: (v, path) => m.projectLine(view(v), path.map((p) => p.position)),
    horizonLine: (v) => m.horizonLine(view(v)),
    findTime: (observer, direction, startUtc, endUtc, options) =>
      m.findTime(observer, direction, startUtc, endUtc, merge(d.searchOptions, options)),
    findDates: (observer, direction, startUtc, endUtc, options) =>
      m.findDates(observer, direction, startUtc, endUtc, merge(d.searchOptions, options)),
    findAzimuthTimes: (observer, azimuthDeg, startUtc, endUtc, options) =>
      m.findAzimuthTimes(observer, azimuthDeg, startUtc, endUtc, merge(d.searchOptions, options)),
    headingPredict: (estimate, dtS, driftDeg2PerS = d.headingDriftDeg2PerS) => m.headingPredict(estimate, dtS, driftDeg2PerS),
    headingUpdate: (estimate, measurement) => m.headingUpdate(estimate, measurement),
    headingFromMagnetometer: (deviceToFrame, fieldUt, observer, unixUtc, options) =>
      m.headingFromMagnetometer(deviceToFrame, fieldUt, observer, unixUtc, merge(d.magnetometerOptions, options)),
    headingFromDirection: (v, point, trueAzimuthDeg, sigmaDeg) =>
      m.headingFromDirection(view(v), point, trueAzimuthDeg, sigmaDeg),
    headingFilterStart: (biasUt, biasSigmaUt, options) =>
      m.headingFilterStart(biasUt, biasSigmaUt, merge(d.headingFilterOptions, options)),
    headingFilterPredict: (filter, dtS, options) =>
      m.headingFilterPredict(filter, dtS, merge(d.headingFilterOptions, options)),
    headingFilterUpdate: (filter, measurement) => m.headingFilterUpdate(filter, measurement),
    headingFilterUpdateMagnetometer: (filter, deviceToFrame, fieldUt, observer, unixUtc, options) =>
      m.headingFilterUpdateMagnetometer(filter, deviceToFrame, fieldUt, observer, unixUtc, merge(d.headingFilterOptions, options)),
  });
}
